type ExtractPII<Type> = {
  [Property in keyof Type]: Type[Property] extends { pii: true }
    ? true
    : false;
};

type DBFields = {
  id: { format: "incrementing" };
  name: { type: string; pii: true };
};

type ObjectsNeedingGDPRDeletion = ExtractPII<DBFields>;

const fields: ObjectsNeedingGDPRDeletion = {
  id: false,
  name: true,
};

type Product = {
  id: string;
  price: number;
  tags: string[];
};

type Price = Product["price"];
type Tag = Product["tags"][number];

declare const product: Product;
const price: Price = product.price;
const tag: Tag = product.tags[0];

type ElementOf<T> = T extends readonly (infer Item)[] ? Item : never;

type Names = ElementOf<readonly ["Ada", "Linus"]>;

const name: Names = "Ada";

type RGB = readonly [number, number, number];
type Colors = "red" | "green" | "blue";

type Palette = Record<Colors, string | RGB>;

const palette = {
  red: [255, 0, 0],
  green: "#00ff00",
  blue: [0, 0, 255],
} as const satisfies Palette;

const firstRedComponent: 255 = palette.red[0];
const greenUpper: string = palette.green.toUpperCase();
console.log(firstRedComponent, greenUpper);

