type Status = "loading" | "success" | "error";

type Result = {
  status: Status;
  message: string;
};

function describe(result: Result): string {
  if (result.status === "success") return result.message;
  return `Request is ${result.status}`;
}

console.log(describe({ status: "success", message: "Ready" }));

type Fish = { swim: () => void };
type Bird = { fly: () => void };

defunction isFish(pet: Fish | Bird): pet is Fish {
  return "swim" in pet;
}

function move(pet: Fish | Bird) {
  if (isFish(pet)) {
    pet.swim();
  } else {
    pet.fly();
  }
}

type Shape =
  | { kind: "circle"; radius: number }
  | { kind: "square"; side: number };

function area(shape: Shape): number {
  switch (shape.kind) {
    case "circle":
      return Math.PI * shape.radius ** 2;
    case "square":
      return shape.side ** 2;
  }
}

